// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.foundation.lazy.rememberLazyListStateimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.SwapHorizimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberCoroutineScopeimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.BrainBarimport com.roshan.persona.ui.components.ConversationListimport com.roshan.persona.ui.components.GlassPanelimport com.roshan.persona.ui.components.InputBarimport com.roshan.persona.ui.components.PersonaAvatarimport com.roshan.persona.ui.state.UiStateProviderimport kotlinx.coroutines.launch/** * Home / Conversation screen — the primary screen of NOUS. * * Wired to [UiStateProvider]: *   - brainHealthPercent, activeBrainLayer, lastBrainLatencyMs, lastBrainCostUsd *   - memoryCount *   - batteryLevel, isCharging, thermalStatus, networkStatus *   - conversationHistory *   - sendVoiceInput(text) — when user sends a message *   - voiceState — when "PROCESSING", show streaming indicator * * @param stateProvider the real UiStateProvider (Hilt-injected) * @param activePersonaId current persona ID * @param activePersonaName current persona display name * @param activePersonaTagline current persona tagline * @param onBrainBarClick open Brain Activity overlay * @param onPersonaSwitcherClick open Persona Switcher sheet * @param onMicClick start/stop voice capture * @param onAttachClick open attachment sheet * @param isMicListening whether mic is currently capturing */@Composablefun HomeScreen(    stateProvider: UiStateProvider,    activePersonaId: String,    activePersonaName: String,    activePersonaTagline: String,    onBrainBarClick: () -> Unit,    onPersonaSwitcherClick: () -> Unit,    onMicClick: () -> Unit,    onAttachClick: () -> Unit,    isMicListening: Boolean,    modifier: Modifier = Modifier,) {    val brainHealth by stateProvider.brainHealthPercent.collectAsState()    val activeLayer by stateProvider.activeBrainLayer.collectAsState()    val latencyMs by stateProvider.lastBrainLatencyMs.collectAsState()    val costUsd by stateProvider.lastBrainCostUsd.collectAsState()    val memoryCount by stateProvider.memoryCount.collectAsState()    val battery by stateProvider.batteryLevel.collectAsState()    val isCharging by stateProvider.isCharging.collectAsState()    val thermal by stateProvider.thermalStatus.collectAsState()    val network by stateProvider.networkStatus.collectAsState()    val conversation by stateProvider.conversationHistory.collectAsState()    val voiceState by stateProvider.voiceState.collectAsState()    val liveTranscription by stateProvider.liveTranscription.collectAsState()    var inputText by remember { mutableStateOf("") }    val scope = rememberCoroutineScope()    val listState = rememberLazyListState()    // Auto-scroll to bottom when conversation updates    LaunchedEffect(conversation.size) {        if (conversation.isNotEmpty()) {            listState.animateScrollToItem(conversation.size - 1)        }    }    Column(        modifier = modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background),    ) {        // Brain Bar        BrainBar(            brainHealth = brainHealth,            activeLayer = activeLayer,            latencyMs = latencyMs,            costUsd = costUsd,            memoryCount = memoryCount,            battery = battery,            isCharging = isCharging,            thermal = thermal,            network = network,            onClick = onBrainBarClick,            modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),        )        // Persona header        Row(            modifier = Modifier                .fillMaxWidth()                .padding(horizontal = 16.dp, vertical = 8.dp)                .clickable(onClick = onPersonaSwitcherClick),            verticalAlignment = Alignment.CenterVertically,        ) {            PersonaAvatar(                personaId = activePersonaId,                displayName = activePersonaName,                size = 48.dp,            )            Spacer(modifier = Modifier.size(12.dp))            Column(modifier = Modifier.weight(1f)) {                Text(                    text = activePersonaName,                    style = MaterialTheme.typography.titleLarge,                    fontWeight = FontWeight.SemiBold,                    color = MaterialTheme.colorScheme.onBackground,                )                Text(                    text = activePersonaTagline,                    style = MaterialTheme.typography.labelMedium,                    color = MaterialTheme.colorScheme.onSurfaceVariant,                )            }            Icon(                imageVector = Icons.Default.SwapHoriz,                contentDescription = "Switch persona",                tint = MaterialTheme.colorScheme.onSurfaceVariant,                modifier = Modifier.size(20.dp),            )        }        // Conversation list (or empty state)        if (conversation.isEmpty()) {            Box(                modifier = Modifier                    .weight(1f)                    .fillMaxWidth(),                contentAlignment = Alignment.Center,            ) {                Column(                    horizontalAlignment = Alignment.CenterHorizontally,                ) {                    Text(                        text = "Hello, I'm $activePersonaName",                        style = MaterialTheme.typography.headlineLarge,                        fontWeight = FontWeight.Bold,                        color = MaterialTheme.colorScheme.onBackground,                    )                    Spacer(modifier = Modifier.size(8.dp))                    Text(                        text = "Tap the mic below or type a message to begin.",                        style = MaterialTheme.typography.bodyLarge,                        color = MaterialTheme.colorScheme.onSurfaceVariant,                    )                }            }        } else {            LazyColumn(                state = listState,                modifier = Modifier                    .weight(1f)                    .fillMaxWidth()                    .padding(horizontal = 16.dp),                verticalArrangement = Arrangement.spacedBy(8.dp),            ) {                items(conversation, key = { item -> "${item.timestamp}_${item.speaker}_${item.text.hashCode()}" }) { item ->                    com.roshan.persona.ui.components.ConversationRow(                        item = item,                        personaId = activePersonaId,                        personaName = activePersonaName,                    )                }                // Live transcription while listening                if (isMicListening && liveTranscription != null) {                    item {                        Text(                            text = liveTranscription ?: "",                            style = MaterialTheme.typography.bodyLarge,                            color = MaterialTheme.colorScheme.onSurfaceVariant,                            modifier = Modifier.padding(8.dp),                        )                    }                }                // "Brain is processing" indicator                if (voiceState == "PROCESSING") {                    item {                        Text(                            text = "● ● ● $activePersonaName is thinking...",                            style = MaterialTheme.typography.labelMedium,                            color = MaterialTheme.colorScheme.primary,                            modifier = Modifier.padding(8.dp),                        )                    }                }            }        }        // Input bar        InputBar(            text = inputText,            onTextChange = { inputText = it },            onSendClick = {                val text = inputText.trim()                if (text.isNotEmpty()) {                    inputText = ""                    scope.launch { stateProvider.sendVoiceInput(text) }                }            },            onMicClick = onMicClick,            onAttachClick = onAttachClick,            isListening = isMicListening,            modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),        )    }}